  // Nicho genérico cuando la persona escribe uno propio: se completa con su texto.
  function nichoPropio(camino, texto) {
    const t = (texto || "tu área").trim();
    const base = {
      id: "propio", nombre: t, tema: t,
      producto: camino === "ugc" ? "el producto de la marca" : camino === "marca-personal" ? `lo que sabes de ${t}` : `lo que ofreces en ${t}`,
      situacion: `te interesa ${t} y no sabes por dónde empezar`,
      momentos: [`preparar mi día de trabajo en ${t}`, `resolver un problema típico de ${t}`, `mostrar cómo hago lo más importante de mi trabajo`, `revisar cómo me fue esta semana`],
      dolores: [`perder tiempo y dinero por no saber cómo funciona ${t}`, "intentarlo sola y no ver resultados", "recibir información contradictoria"],
      deseos: ["resultados claros sin complicarse", "alguien de confianza que le explique", "avanzar paso a paso"],
      errores: ["empezar sin informarse", "copiar lo que hace otra persona", "rendirse antes de ver resultados"],
      mitos: [`${t} es solo para expertos`, "lo caro siempre es mejor", "se necesita mucho tiempo para ver resultados"],
      tips: ["empieza por lo básico antes de complicarte", "pregunta siempre qué incluye y qué no", "mide tu avance cada semana"],
      preguntas: ["¿Por dónde empiezo?", "¿Cuánto cuesta?", "¿En cuánto tiempo veo resultados?"]
    };
    return base;
  }

